export interface RetryOptions {
  attempts?: number;      // max total attempts (default 3)
  baseDelayMs?: number;   // base delay in ms (default 200)
  maxDelayMs?: number;    // cap on delay (default 5000)
  factor?: number;        // exponential multiplier (default 2)
