export class RetryCancelledError extends Error {
  constructor(message = 'Retry operation cancelled') {
    super(message);
    this.name = 'RetryCancelledError';
  }
}

function sleep(ms: number, token: CancellationToken): Promise<void> {
  return new Promise((resolve, reject) => {
    if (token.isCancelled) {
      reject(new RetryCancelledError());
      return;
    }
    const timer = setTimeout(() => {
      token.off('cancel', onCancel);
      resolve();
    }, ms);
    const onCancel = () => {
      clearTimeout(timer);
      reject(new RetryCancelledError());
    };
    token.on('cancel', onCancel);
  });
}

export class CancellationToken {
  private _cancelled = false;
  private readonly listeners: Array<() => void> = [];

  get isCancelled(): boolean {
    return this._cancelled;
  }

  cancel(): void {
    if (this._cancelled) return;
    this._cancelled = true;
    for (const l of this.listeners) l();
  }
